import { Table, BooleanColumn, ReferenceColumn, StringColumn, GuidColumn } from '@servicenow/sdk/core'

export const sla_condition_class = Table({
    name: 'sla_condition_class',
    extends: 'sys_metadata',
    schema: {
        active: BooleanColumn({
            default: true,
            label: 'Active',
        }),
        class_name: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Class name',
            referenceTable: 'sys_script_include',
        }),
        name: StringColumn({
            label: 'Name',
        }),
        sys_id: GuidColumn({
            label: 'Sys ID',
            primary: true,
        }),
    },
})
